mapper.insert:
INSERT INTO wo_workbook_master (
    WORKBOOK_NAME, OWNER_USER, DOC_VER, DOC_TYPE, USE_YN,
    INPUT_DATETIME, INPUT_USER
) VALUES (
    #{workbook.workbookName}, #{workbook.ownerUser}, 1,

    COALESCE(#{workbook.docType}, 'SHEET'), 'Y',
    CURRENT_TIMESTAMP, #{userKey}
)

mapper.select:
SELECT S.WORKBOOK_SEQ, C.ROW_NO, C.COLUMN_NO, C.TEXT_VALUE AS TEXT FROM wo_sheet_cell_line C JOIN wo_workbook_sheet_line S ON S.SHEET_SEQ = C.SHEET_SEQ WHERE S.SHEET_NO = 0 AND S.DEL_DATETIME IS NULL AND C.ROW_NO < #{rowCount} AND C.COLUMN_NO < #{columnCount} AND C.TEXT_VALUE IS NOT NULL AND S.WORKBOOK_SEQ IN
#{seq}
ORDER BY S.WORKBOOK_SEQ, C.ROW_NO, C.COLUMN_NO

mapper.update:
UPDATE wo_workbook_master
   SET WORKBOOK_NAME = #{workbookName},
       MOD_DATETIME  = CURRENT_TIMESTAMP,
       MOD_USER       = #{userKey}
 WHERE WORKBOOK_SEQ  = #{workbookSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_master
   SET SHARE_TOKEN   = NULL,
       DEL_DATETIME  = CURRENT_TIMESTAMP,
       DEL_USER       = #{userKey}
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND DEL_DATETIME IS NULL

mapper.select:
SELECT WORKBOOK_SEQ, WORKBOOK_NAME, DOC_TYPE, DEL_DATETIME AS DELETED_AT
  FROM wo_workbook_master
 WHERE OWNER_USER = #{userKey}
   AND DEL_DATETIME IS NOT NULL
   AND DEL_DATETIME >= #{since}
 ORDER BY DEL_DATETIME DESC, WORKBOOK_SEQ DESC

mapper.update:
UPDATE wo_workbook_master
   SET DEL_DATETIME = NULL,
       DEL_USER      = NULL,
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND OWNER_USER    = #{userKey}
   AND DEL_DATETIME IS NOT NULL
   AND DEL_DATETIME >= #{since}

UPDATE wo_workbook_master
   SET SHARE_TOKEN  = #{shareToken},
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND DEL_DATETIME IS NULL

UPDATE wo_workbook_master
   SET DOC_VER      = DOC_VER + 1,
       MOD_DATETIME = CURRENT_TIMESTAMP,
       MOD_USER      = #{userKey}
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND DOC_VER      = #{expectedDocVer}
   AND DEL_DATETIME IS NULL
